with session_totals as (select session_id, sum(case when page = '/product' then duration_sec else 0 end) as product_duration_sec, round(avg(duration_sec), 2) as avg_duration_sec from web_events where event_type = 'search' group by session_id) select s.id, s.customer_id, st.product_duration_sec, st.avg_duration_sec from sessions s left outer join session_totals st on s.id = st.session_id;
